        <g key={i}>
          <rect x={128 + i * 6} y={bas - 22 - i * 12} width="22" height="14" fill="#b45309" />
          <rect x={128 + i * 6} y={bas - 22 - i * 12} width="22" height="3" fill="#d97706" />
          <rect x={137 + i * 6} y={bas - 22 - i * 12} width="4" height="14" fill="#fde68a" />
        </g>
      ))}
    </g>
  )
}

