          <theme.BureauChef {...bureau} />
          {/* La plaque du chef, en laiton, tournée vers la pièce. */}
          <rect x={cx - 42} y={dy + dessus + 1} width="84" height="9" fill="#b8892f" />
          <rect x={cx - 41} y={dy + dessus + 2} width="82" height="7" fill="#e3b95a" />
          <Lampe x={cx - 37} y={dy + dessus + 3} statut={statut} />
          <text x={cx + 3} y={dy + dessus + 8.5} fontSize="8" textAnchor="middle" fill="#4a3412">
            {fiche.nom}
          </text>
        </>
      ) : (
        <>
          <theme.Bureau {...bureau} />
          {/* La tranche porte le nom, avec la lampe. */}
          <Lampe x={x + 6} y={dy + dessus + 3} statut={statut} />
          <text x={cx + 4} y={dy + dessus + 8.5} fontSize="9" textAnchor="middle" fill={theme.plaque} opacity={allume ? 1 : 0.5}>
            {fiche.nom}
          </text>
          {oublie ? <Poussiere cx={cx} dy={dy} /> : null}
          <PlanteDeBureau x={x - 15} y={dy + 30} fanee={oublie} />

          {/* Le siège : l'assise seule quand l'agent y est (son dossier passe devant lui), repoussé sinon. */}
          {occupe ? (
            <theme.Assise x={chaise.x} y={chaise.y} couleur={accent} />
          ) : (
            <g transform="translate(9 3)">
              <theme.Assise x={chaise.x} y={chaise.y} couleur={accent} />
              <theme.Dossier x={chaise.x} y={chaise.y} couleur={accent} />
            </g>
          )}
        </>
      )}
    </g>
  )
}

function Lampe({ x, y, statut }: { x: number; y: number; statut: Statut }) {
  return (
    <rect x={x} y={y} width="5" height="5" fill={LAMPE_PLAN[statut]}>
      {statut === 'au-travail' || statut === 'en-echec' ? (
        <Anim attributeName="opacity" values="1;0.3;1" dur="1.2s" repeatCount="indefinite" />
      ) : null}
    </rect>
  )
}

type Direction = 'haut' | 'bas' | 'gauche' | 'droite'

function direction(angle: number): Direction {
  const a = ((angle % 360) + 360) % 360
  if (a < 45 || a >= 315) return 'haut'
  if (a < 135) return 'droite'
  if (a < 225) return 'bas'
  return 'gauche'
}

/* Un bonhomme fait 8 pixels sur 12 : la tête, le sweat à capuche, les jambes. */
const TETE: Record<'haut' | 'bas' | 'droite', Array<string>> = {
  bas: ['..hhhh..', '.hhhhhh.', '.hssssh.', '.sesses.', '.cssssc.'],
  haut: ['..hhhh..', '.hhhhhh.', '.hhhhhh.', '.hhhhhh.', '.cchhcc.'],
  droite: ['..hhhh..', '.hhhhhh.', '.hhhsss.', '.hhhses.', '.ccsss..'],
}
/* La même, casque audio sur les oreilles. */
const TETE_CASQUE: Record<'haut' | 'bas' | 'droite', Array<string>> = {
  bas: ['..kkkk..', '.khhhhk.', 'khsssshk', 'ksessesk', '.cssssc.'],
  haut: ['..kkkk..', '.khhhhk.', 'khhhhhhk', 'khhhhhhk', '.cchhcc.'],
  droite: ['..kkkk..', '.hhhkhh.', '.hhkkss.', '.hhkses.', '.ccsss..'],
}
/* Le sweat : la poche ventrale et les cordons de capuche (`t`). */
const BUSTE: Record<'haut' | 'bas' | 'droite', Array<string>> = {
  bas: ['.ctcctc.', 'cctcctcc', 'sccccccs', '.cCCCCc.'],
  haut: ['.cccccc.', 'cccccccc', 'sccccccs', '.cccccc.'],
  droite: ['..cccc..', '..cccc..', '..ccsc..', '..cCCc..'],
}
/* Les jambes : debout, puis les deux temps du pas. */
const JAMBES: Record<'face' | 'cote', Array<Array<string>>> = {
  face: [
    ['.pp..pp.', '.pp..pp.', '.bb..bb.'],
    ['.pp..pp.', '.pp..bb.', '.bb.....'],
    ['.pp..pp.', '.bb..pp.', '.....bb.'],
  ],
  cote: [
    ['..pppp..', '..pp.p..', '..bb.bb.'],
    ['..pppp..', '.pp...p.', '.bb...bb'],
    ['..pppp..', '...pp...', '...bbb..'],
  ],
}

/* Les bras levés de l'agent qui s'étire, vu de dos. */
const ETIREMENT = ['s.hhhh.s', 'chhhhhhc', 'chhhhhhc', 'chhhhhhc', 'c.hhhh.c', '.cccccc.', 'cccccccc', 'cccccccc']

function grilleSprite(sens: Direction, temps: number, assise: Assise, etire: boolean, casque: boolean): Array<string> {
  if (etire && assise === 'bureau' && sens === 'haut') return ETIREMENT
  const tete = casque ? TETE_CASQUE : TETE
  // Au bureau ou sur un pouf, de dos devant l'écran ; le chef, lui, trône face à la pièce.
  if (assise) return sens === 'bas' ? [...tete.bas, ...BUSTE.bas.slice(0, 3)] : [...tete.haut, ...BUSTE.haut.slice(0, 3)]
  const miroir = sens === 'gauche'
  const s = miroir ? 'droite' : sens
  const g = [...tete[s], ...BUSTE[s], ...JAMBES[s === 'droite' ? 'cote' : 'face'][temps]]
  return miroir ? g.map((l) => [...l].reverse().join('')) : g
}

const CONTOUR = Object.fromEntries([...'hsectCkpb'].map((c) => [c, '#0b0d10']))

/** Le bonhomme, contour sombre compris. Mémorisé : il ne change qu'au pas suivant. */
const Sprite = memo(function Sprite({
  id,
  sens,
  temps,
  assise,
  etire,
}: {
  id: string
  sens: Direction
  temps: number
  assise: Assise
  etire: boolean
}) {
  const theme = useTheme()
  const grille = grilleSprite(sens, temps, assise, etire, theme.casque(id))
  return (
    <>
      {[
        [-1, 0],
        [1, 0],
        [0, -1],
        [0, 1],
      ].map(([dx, dy]) => (
        <g key={`${dx}${dy}`} transform={`translate(${dx} ${dy})`}>
          <Pixels grille={grille} couleurs={CONTOUR} />
        </g>
      ))}
      <Pixels grille={grille} couleurs={theme.tenue(id)} />
    </>
  )
})

/** La hauteur du sprite au-dessus du point où il se tient, et le haut de sa tête. */
function cadrage(pose: Pose) {
  const rangs = pose.assise ? 8 : 12
  // Assis, il s'enfonce dans son fauteuil ou son pouf : au bureau, sa tête passe sous la plaque.
  const bas = pose.assise ? pose.y + 8 : pose.y
  return { haut: bas - rangs * 3, bas }
}

function Personnage({ id, pose, etire, choisir }: { id: string; pose: Pose; etire: boolean; choisir?: (id: string) => void }) {
  const theme = useTheme()
  const temps = pose.marche ? 1 + (Math.floor(pose.pas / 170) % 2) : 0
  const { haut, bas } = cadrage(pose)
  return (
    <g className={choisir ? 'cursor-pointer' : undefined} onClick={choisir ? () => choisir(id) : undefined}>
      {pose.assise ? null : <ellipse cx={pose.x} cy={bas} rx="10" ry="3" fill="black" opacity="0.3" shapeRendering="auto" />}
      <g transform={`translate(${Math.round(pose.x) - 12} ${Math.round(haut)})`}>
        <Sprite id={id} sens={direction(pose.angle)} temps={temps} assise={pose.assise} etire={etire} />
        {/* Le colis du livreur, porté à bout de bras. */}
        {pose.porte ? (
          <g>
            <rect x="3" y="17" width="18" height="12" fill="#b45309" />
            <rect x="3" y="17" width="18" height="3" fill="#d97706" />
            <rect x="10" y="17" width="4" height="12" fill="#fde68a" />
          </g>
        ) : !pose.assise && theme.tasse?.(id) ? (
          /* La tasse, tenue à la main droite. */
          <g>
            <rect x="18" y="19" width="6" height="7" fill="#0b0d10" />
            <rect x="19" y="20" width="4" height="5" fill="#fafaf9" />
            <rect x="24" y="21" width="2" height="3" fill="#0b0d10" />
            <rect x="19" y="20" width="4" height="1" fill="#6b3a1e" />
          </g>
        ) : null}
      </g>
    </g>
  )
}

/**
 * Au-dessus de la tête, une chose à la fois : la bulle de celui qui parle,
 * l'icône de celui qui a un souci, ou l'étiquette de celui qui travaille.
 */
function Annonce({ vue, pose, parole }: { vue: Vue; pose: Pose; parole: string | null }) {
  const t = useTextes()
  const { statut, fiche } = vue
  const { haut } = cadrage(pose)
  const x = Math.round(pose.x)

  if (parole) return <Parole x={x} haut={haut} texte={parole} />

  if (pose.assise === 'bureau' && (statut === 'en-echec' || statut === 'en-retard')) {
    return (
      <g transform={`translate(${x + 10} ${haut - 14})`} pointerEvents="none">
        <rect width="16" height="14" fill="#1b1410" />
        <rect x="1" y="1" width="14" height="12" fill={statut === 'en-echec' ? '#ef4444' : '#fb923c'} />
        <text x="8" y="11" fontSize="10" textAnchor="middle" fill="white">
          {statut === 'en-echec' ? '!' : 'z'}
        </text>
        <Anim
          attributeName="transform"
          type="translate"
          values={`${x + 10} ${haut - 14};${x + 10} ${haut - 17};${x + 10} ${haut - 14}`}
          dur="1.4s"
          repeatCount="indefinite"
        />
      </g>
    )
  }

  if (statut !== 'au-travail') return null
  const libelle = t.statuses[statut]
  const largeur = Math.round(Math.max(fiche.nom.length * 5.4, libelle.length * 4.6 + 12) + 12)
  return (
    <g transform={`translate(${x - Math.round(largeur / 2)} ${haut - 30})`} pointerEvents="none">
      <rect width={largeur} height="26" fill="#1b1410" />
      <rect x="1" y="1" width={largeur - 2} height="24" fill="#2b2420" />
      <text x="6" y="11" fontSize="9" fill="#fafaf9">
        {fiche.nom}
      </text>
      <rect x="6" y="15" width="5" height="5" fill={LAMPE_PLAN[statut]} />
      <text x="14" y="21" fontSize="8" fill={LAMPE_PLAN[statut]}>
        {libelle}
      </text>
    </g>
  )
}

/** Une bulle de bande dessinée, en pixels ; « … » fait danser trois points. */
function Parole({ x, haut, texte }: { x: number; haut: number; texte: string }) {
  const points = texte === '…'
  const court = texte.length > 46 ? `${texte.slice(0, 45)}…` : texte
  const largeur = points ? 26 : Math.round(court.length * 4.5 + 12)
  const gauche = Math.min(Math.max(x - largeur / 2, 8), LARGEUR - largeur - 8)
  const y = haut - 24
  return (
    <g pointerEvents="none">
      <rect x={gauche - 1} y={y - 1} width={largeur + 2} height="18" fill="#1b1410" />
      <rect x={gauche} y={y} width={largeur} height="16" fill="#fafaf9" />
      <rect x={x - 4} y={y + 16} width="8" height="3" fill="#fafaf9" />
      <rect x={x - 1} y={y + 19} width="3" height="3" fill="#fafaf9" />
      {points ? (
        [7, 13, 19].map((dx, i) => (
          <rect key={dx} x={gauche + dx - 1} y={y + 7} width="3" height="3" fill="#44403c">
            <Anim attributeName="opacity" values="0.2;1;0.2" dur="1s" begin={`${i * 0.2}s`} repeatCount="indefinite" />
          </rect>
        ))
      ) : (
        <text x={gauche + 6} y={y + 11} fontSize="8" fill="#1c1917">
          {court}
        </text>
      )}
    </g>
  )
}

/**
 * Le plan de l'open space et la vie qui s'y mène : où sont les bureaux, le
 * coin café, le bureau vitré du chef, et comment chacun s'y déplace. Sans
 * React ni DOM, pour que les trajets se testent seuls ; la page dessine ce
 * que `avancer` calcule.
 *
 * Les coordonnées sont celles du `viewBox` SVG. Un angle de 0 regarde vers le
 * haut, 90 vers la droite.
 */

import { TEXTS, type Phrases } from './i18n'

/** An agent's state, as the engine reads it. */
export type Statut = 'au-travail' | 'a-jour' | 'en-retard' | 'en-echec' | 'absent' | 'jamais' | 'a-la-demande'

export type Point = { x: number; y: number }

/**
 * Un endroit où se tenir, le chemin qui y mène depuis l'allée, où regarder
 * une fois arrivé, et si l'on s'y assoit.
 */
export type Lieu = { nom: string; pos: Point; acces: Array<Point>; face: number; assis?: boolean }

/** Où aller, combien de temps y rester, et ce qu'on y dit en arrivant. */
export type Etape = { lieu: Lieu; pause: number; dire?: string }

export const LARGEUR = 1000
const COLONNES = 5
/** Le plateau d'un bureau. */
export const BUREAU = { largeur: 120, hauteur: 50 }
const PAS = 175
const X0 = 150
const HAUT = 300
const RANGEE = 170
/** L'allée du haut, qui longe le bureau du chef et le coin café. */
const ALLEE_HAUT = 262
/** Des unités du plan par seconde : un pas tranquille. */
const VITESSE = 85

export const CHEF_ID = 'chef'

export type PlaceBureau = { id: string; cx: number; dy: number; siege: Lieu; visite: Lieu }

export type Plan = {
  hauteur: number
  bureaux: Array<PlaceBureau>
  chef: PlaceBureau
  /** Les coins où l'on va se dégourdir les jambes. */
  pauses: Array<Lieu>
  /** La porte d'entrée, en bas de la grande salle, par où passent visiteurs et livreurs. */
  entree: Lieu
  /** Le pied de la pile de cartons, où le livreur dépose son colis. */
  cartons: Lieu
  /** Devant le grand écran mural, où le chef fait son rapport. */
  ecranMural: Lieu
  /** Ce que disent les gens de la salle, dans la langue choisie. */
  phrases: Phrases
  /** Les passages verticaux entre les colonnes de bureaux. */
  couloirs: Array<number>
}

const chaiseY = (dy: number) => dy + BUREAU.hauteur + 22

/**
 * Un coin de pause d'un thème, dans les pièces du haut : où se tenir, où regarder
 * (0 vers le haut, 180 vers le bas), et si l'on s'y assoit. Le premier compte
 * double, comme le second : c'est le café et son voisin.
 */
export type CoinDePause = { nom: string; x: number; y: number; face?: number; assis?: boolean }

/* Les coins du thème geek : la cuisine à droite, le coin gaming au milieu. */
export const COINS_GEEK: Array<CoinDePause> = [
  { nom: 'cafe', x: 768, y: 100 },
  { nom: 'distributeur', x: 881, y: 104 },
  { nom: 'frigo', x: 950, y: 108 },
  { nom: 'arcade', x: 372, y: 112 },
  { nom: 'arcade-2', x: 415, y: 112 },
  { nom: 'etabli', x: 636, y: 108 },
  // Sur les poufs, face à la télé : de dos.
  { nom: 'pouf-gauche', x: 482, y: 146, assis: true },
  { nom: 'pouf-droite', x: 538, y: 146, assis: true },
]

export function plan(ids: Array<string>, phrases: Phrases = TEXTS.en.phrases, coins: Array<CoinDePause> = COINS_GEEK): Plan {
  const rangees = Math.max(1, Math.ceil(ids.length / COLONNES))
  const bureaux = ids.map((id, i) => {
    const cx = X0 + (i % COLONNES) * PAS
    const dy = HAUT + Math.floor(i / COLONNES) * RANGEE
    const allee = dy + 108
    return {
      id,
      cx,
      dy,
      siege: { nom: `siege:${id}`, pos: { x: cx, y: chaiseY(dy) - 4 }, acces: [{ x: cx, y: allee }], face: 0, assis: true },
      visite: { nom: `visite:${id}`, pos: { x: cx + 76, y: chaiseY(dy) }, acces: [{ x: cx + 76, y: allee }], face: -90 },
    }
  })

  // Le chef trône derrière son bureau, face à la pièce : il en fait le tour par la droite pour s'asseoir.
  const chef: PlaceBureau = {
    id: CHEF_ID,
    cx: 205,
    dy: 110,
    siege: {
      nom: 'siege:chef',
      pos: { x: 205, y: 102 },
      acces: [
        { x: 260, y: ALLEE_HAUT },
        { x: 260, y: 182 },
        { x: 300, y: 182 },
        { x: 300, y: 96 },
        { x: 205, y: 96 },
      ],
      face: 180,
      assis: true,
    },
    visite: {
      nom: 'visite:chef',
      pos: { x: 300, y: 140 },
      acces: [
        { x: 260, y: ALLEE_HAUT },
        { x: 260, y: 182 },
        { x: 300, y: 182 },
      ],
      face: -90,
    },
  }

  // Les coins de pause viennent du thème : on y entre par le bas, droit devant soi, depuis l'allée du haut.
  const pauses: Array<Lieu> = coins.map((c) => ({
    nom: c.nom,
    pos: { x: c.x, y: c.y },
    acces: [{ x: c.x, y: ALLEE_HAUT }],
    face: c.face ?? 0,
    assis: c.assis ?? false,
  }))

  const hauteur = HAUT + rangees * RANGEE + 10
  const derniereAllee = HAUT + (rangees - 1) * RANGEE + 108
  return {
    hauteur,
    bureaux,
    chef,
    pauses,
    phrases,
    entree: { nom: 'entree', pos: { x: 500, y: hauteur - 26 }, acces: [{ x: 500, y: derniereAllee }], face: 0 },
    cartons: { nom: 'cartons', pos: { x: 140, y: hauteur - 46 }, acces: [{ x: 140, y: derniereAllee }], face: -90 },
    ecranMural: { nom: 'ecran-mural', pos: { x: 130, y: ALLEE_HAUT + 4 }, acces: [{ x: 130, y: ALLEE_HAUT }], face: 0 },
    couloirs: Array.from({ length: COLONNES + 1 }, (_, k) => X0 - PAS / 2 + k * PAS),
  }
}

/**
 * Le chemin d'un lieu à un autre : sortir par son accès jusqu'à l'allée,
 * changer d'allée par le couloir le plus proche, puis entrer par l'accès du
 * lieu visé. On ne traverse jamais un bureau.
 */
export function trajet(de: Lieu, vers: Lieu, couloirs: Array<number>): Array<Point> {
  if (de === vers) return []
  const points = [...de.acces].reverse()
  const a = points.at(-1) ?? de.pos
  const b = vers.acces[0] ?? vers.pos
  if (Math.abs(a.y - b.y) > 1) {
    const milieu = (a.x + b.x) / 2
    const x = couloirs.reduce((p, c) => (Math.abs(c - milieu) < Math.abs(p - milieu) ? c : p))
    points.push({ x, y: a.y }, { x, y: b.y })
  }
  points.push(...vers.acces, vers.pos)
  return points
}

export type Marcheur = {
  id: string
  pos: Point
  angle: number
  lieu: Lieu
  chemin: Array<Point>
  /** Le temps à rester où l'on est, en ms. */
  attente: number
  programme: Array<Etape>
  /** Le temps passé à marcher, qui balance les pieds. */
  pas: number
  /** Ce qu'il dira en arrivant, puis ce qu'il dit une fois arrivé. */
  dire: string | null
  parole: string | null
  /** Le livreur porte son colis jusqu'aux cartons. */
  porte: boolean
  /** Un visiteur ressorti par la porte : la page peut l'oublier. */
  parti: boolean
}

export function marcheur(id: string, siege: Lieu, attente: number): Marcheur {
  return {
    id,
    pos: { ...siege.pos },
    angle: siege.face,
    lieu: siege,
    chemin: [],
    attente,
    programme: [],
    pas: 0,
    dire: null,
    parole: null,
    porte: false,
    parti: false,
  }
}

/** Ceux qui ne font que passer : le client qui apporte sa demande, le livreur et son colis. */
export type Invite = 'visiteur' | 'livreur'

export const estInvite = (id: string) => id.startsWith('visiteur:') || id.startsWith('livreur:')

export const CHAT_ID = 'chat'

/** Le chat d'atelier, qui commence sa journée roulé sur un siège. */
export function chat(p: Plan): Marcheur {
  // Le dernier siège du thème (un pouf, un banc…), sinon le premier coin venu.
  const pouf = [...p.pauses].reverse().find((l) => l.assis) ?? p.pauses[0]
  return marcheur(CHAT_ID, pouf, 6_000)
}

/** Le dessus d'un bureau, où le chat saute faire la sieste. */
const bureauDuChat = (b: PlaceBureau): Lieu => {
  const allee = b.siege.acces[0].y
  return { nom: `bureau-chat:${b.id}`, pos: { x: b.cx + 32, y: b.dy + 38 }, acces: [{ x: b.cx + 32, y: allee }], face: 90, assis: true }
}

/**
 * Le chat va où il veut : faire la sieste sur un bureau dont l'agent s'est
 * levé (ou est absent), traîner au coin café ou sur les poufs, longtemps.
 */
function programmeChat(p: Plan, marcheurs: Array<Marcheur>, statuts: Map<string, Statut>, hasard: () => number): Array<Etape> {
  const libres = p.bureaux.filter((b) => {
    const agent = marcheurs.find((m) => m.id === b.id)
    return statuts.get(b.id) === 'absent' || (agent && agent.lieu !== b.siege)
  })
  if (libres.length && hasard() < 0.6) {
    const b = libres[Math.floor(hasard() * libres.length)]
    return [{ lieu: bureauDuChat(b), pause: entre(180_000, 360_000, hasard), dire: 'z' }]
  }
  const coin = p.pauses[Math.floor(hasard() * p.pauses.length)]
  return [{ lieu: coin, pause: entre(60_000, 180_000, hasard) }]
}

/**
 * Un invité entre par la porte : le visiteur va saluer le chef dans son
 * bureau, le livreur dépose son colis au pied des cartons ; puis chacun
 * ressort par où il est venu.
 */
export function invite(p: Plan, genre: Invite, numero: number): Marcheur {
  const m = marcheur(`${genre}:${numero}`, p.entree, 0)
  m.programme =
    genre === 'visiteur'
      ? [
          { lieu: p.chef.visite, pause: 5_000, dire: p.phrases.visitor },
          { lieu: p.entree, pause: 0 },
        ]
      : [
          { lieu: p.cartons, pause: 3_000, dire: p.phrases.courier },
          { lieu: p.entree, pause: 0 },
        ]
  m.porte = genre === 'livreur'
  return m
}

/** Ceux que leur état cloue au bureau : le travail, ou le souci qui les y retient. */
export const auBureau = (s: Statut | undefined) => s === 'au-travail' || s === 'en-echec' || s === 'en-retard'

function partir(m: Marcheur, etape: Etape, couloirs: Array<number>) {
  m.chemin = trajet(m.lieu, etape.lieu, couloirs)
  m.lieu = etape.lieu
  m.attente = etape.pause
  m.dire = etape.dire ?? null
  m.parole = null
  if (!m.chemin.length) arriver(m)
}

function arriver(m: Marcheur) {
  m.angle = m.lieu.face
  m.parole = m.dire
  if (m.lieu.nom === 'cartons') m.porte = false
}

function marcher(m: Marcheur, dt: number) {
  let reste = (VITESSE * dt) / 1000
  while (reste > 0 && m.chemin.length) {
    const cible = m.chemin[0]
    const dx = cible.x - m.pos.x
    const dy = cible.y - m.pos.y
    const d = Math.hypot(dx, dy)
    if (d > 0.01) m.angle = (Math.atan2(dx, -dy) * 180) / Math.PI
    if (d <= reste) {
      m.pos = { ...cible }
      m.chemin.shift()
      reste -= d
    } else {
      m.pos = { x: m.pos.x + (dx / d) * reste, y: m.pos.y + (dy / d) * reste }
      reste = 0
    }
  }
  m.pas += dt
  if (!m.chemin.length) arriver(m)
}

const entre = (min: number, max: number, hasard: () => number) => min + hasard() * (max - min)

/** Un agent désœuvré : un tour au café, à la fontaine ou chez un collègue, puis retour au bureau. */
function programmeAgent(p: Plan, place: PlaceBureau, presents: Array<PlaceBureau>, hasard: () => number): Array<Etape> {
  const collegues = presents.filter((b) => b.id !== place.id).map((b) => b.visite)
  const collegue = collegues[Math.floor(hasard() * collegues.length)]
  // Le café et la fontaine comptent double, et l'on passe parfois voir un collègue.
  const choix = [...p.pauses, ...p.pauses.slice(0, 2), ...(collegue ? [collegue, collegue] : [])]
  const lieu = choix[Math.floor(hasard() * choix.length)] ?? p.pauses[0]
  return [
    // Chez un collègue, on bavarde. Les sorties sont rares et longues : moins de pas, moins à redessiner.
    { lieu, pause: entre(30_000, 90_000, hasard), dire: lieu === collegue ? '…' : undefined },
    { lieu: place.siege, pause: entre(180_000, 480_000, hasard) },
  ]
}

/**
 * Le chef en ronde commence par ceux qui ont un souci, qu'il relance, puis
 * passe aux autres bureaux. Hors de sa ronde, il reste au chevet d'un agent
 * en échec jusqu'à ce qu'il soit relancé ; sinon il va voir qui est en
 * retard, ou se sert un café.
 */
function programmeChef(
  p: Plan,
  statut: Statut | undefined,
  presents: Array<PlaceBureau>,
  soucis: Array<PlaceBureau>,
  echecs: Set<string>,
  annonces: Array<string>,
  hasard: () => number,
): Array<Etape> {
  const annoncer = annonces.map((a) => ({ lieu: p.ecranMural, pause: 6_000, dire: a }))
  if (statut === 'au-travail') {
    const autres = presents.filter((b) => !soucis.includes(b))
    const rapport = p.phrases.report(autres.length, soucis.length)
    return [
      ...soucis.map((b) => ({ lieu: b.visite, pause: 3_500, dire: p.phrases.relaunch })),
      ...autres.map((b) => ({ lieu: b.visite, pause: 1_500 })),
      // La ronde finie, il fait son rapport devant le grand écran.
      { lieu: p.ecranMural, pause: 6_000, dire: rapport },
      // Puis ce qui ne doit pas être oublié : les annonces qu'on lui a confiées.
      ...annoncer,
      { lieu: p.chef.siege, pause: 3_000 },
    ]
  }
  const enEchec = soucis.find((b) => echecs.has(b.id))
  if (enEchec) return [{ lieu: enEchec.visite, pause: 60_000, dire: p.phrases.stayingHere }]
  // Une annonce en attente : de temps en temps, il va la redire devant l'écran.
  if (annoncer.length && hasard() < 0.5) return [...annoncer, { lieu: p.chef.siege, pause: entre(240_000, 600_000, hasard) }]
  const souci = soucis.length ? soucis[Math.floor(hasard() * soucis.length)] : null
  return [
    souci
      ? { lieu: souci.visite, pause: entre(3_000, 5_000, hasard), dire: p.phrases.anyTrouble }
      : { lieu: p.pauses[0], pause: entre(3_000, 5_000, hasard) },
    { lieu: p.chef.siege, pause: entre(240_000, 600_000, hasard) },
  ]
}

/** Fait vivre l'open space pendant `dt` millisecondes. */
export function avancer(
  p: Plan,
  marcheurs: Array<Marcheur>,
  statuts: Map<string, Statut>,
  dt: number,
  hasard: () => number = Math.random,
  annonces: Array<string> = [],
  /** La nuit, les désœuvrés regagnent leur bureau et n'en bougent plus ; le chat dort où il est. */
  nuit = false,
) {
  const presents = p.bureaux.filter((b) => statuts.get(b.id) !== 'absent')
  const soucis = presents.filter((b) => ['en-echec', 'en-retard'].includes(statuts.get(b.id) ?? ''))
  const echecs = new Set(soucis.filter((b) => statuts.get(b.id) === 'en-echec').map((b) => b.id))

  for (const m of marcheurs) {
    if (m.id === CHAT_ID) {
      if (m.chemin.length) marcher(m, dt)
      else if (!nuit && (m.attente -= dt) <= 0) partir(m, programmeChat(p, marcheurs, statuts, hasard)[0], p.couloirs)
      continue
    }
    if (estInvite(m.id)) {
      if (m.chemin.length) marcher(m, dt)
      else if ((m.attente -= dt) > 0) continue
      else if (m.programme.length) partir(m, m.programme.shift()!, p.couloirs)
      else m.parti = true
      continue
    }
    const chef = m.id === CHEF_ID
    const place = chef ? p.chef : p.bureaux.find((b) => b.id === m.id)
    if (!place) continue
    const statut = statuts.get(m.id)

    if (m.chemin.length) {
      marcher(m, dt)
      continue
    }
    if (statut === 'absent') {
      Object.assign(m, marcheur(m.id, place.siege, 0))
      continue
    }
    const cloue = chef ? statut === 'en-echec' || statut === 'en-retard' : auBureau(statut)
    if (cloue) {
      m.programme = []
      if (m.lieu !== place.siege) partir(m, { lieu: place.siege, pause: 1_000 }, p.couloirs)
      continue
    }
    // Le chef lancé pendant qu'il est assis part en ronde sans finir son café.
    if (chef && statut === 'au-travail' && m.lieu === place.siege && !m.programme.length) m.attente = Math.min(m.attente, 1_500)
    // Au chevet d'un agent qui n'est plus en échec, il s'en va ; et un nouvel échec le fait se lever.
    if (chef && !m.programme.length) {
      const veille = m.lieu.nom.startsWith('visite:') ? m.lieu.nom.slice('visite:'.length) : null
      if (veille && m.dire === p.phrases.stayingHere && !echecs.has(veille)) m.attente = Math.min(m.attente, 1_000)
      if (m.lieu === place.siege && echecs.size && statut !== 'au-travail') m.attente = Math.min(m.attente, 2_000)
    }

    // La nuit, hors de la ronde du chef, chacun reste ou rentre à son bureau.
    if (nuit && !(chef && statut === 'au-travail')) {
      m.programme = []
      if (m.lieu !== place.siege) partir(m, { lieu: place.siege, pause: 1_000 }, p.couloirs)
      continue
    }
    m.attente -= dt
    if (m.attente > 0) continue
    if (!m.programme.length) {
      m.programme = chef ? programmeChef(p, statut, presents, soucis, echecs, annonces, hasard) : programmeAgent(p, place, presents, hasard)
    }
    partir(m, m.programme.shift()!, p.couloirs)
  }
}

'use client'

import { useEffect, useState } from 'react'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { Kbd } from '@/components/ui/kbd'
import type { Texts } from './i18n'

/** Les jeux des deux bornes du coin gaming. */
export type Jeu = 'snake' | 'casse-briques'

/** La toile, carrée, en pixels. */
const COTE = 320

type Partie = {
  /** Appelé à chaque point marqué, avec le total. */
  marquer: (points: number) => void
  /** Appelé quand la partie est perdue. */
  perdre: () => void
}

/** Ce qu'une borne sait de son jeu : son nom, ses couleurs, ses commandes, et comment le lancer. */
const BORNES: Record<
  Jeu,
  { cadre: string; fond: string; accent: string; lancer: (ctx: CanvasRenderingContext2D, p: Partie) => () => void }
> = {
  snake: {
    cadre: 'border-violet-700',
    fond: 'bg-violet-950',
    accent: 'text-pink-400',
    lancer: lancerSnake,
  },
  'casse-briques': {
    cadre: 'border-cyan-600',
    fond: 'bg-slate-950',
    accent: 'text-cyan-300',
    lancer: lancerCasseBriques,
  },
}

const cleRecord = (jeu: Jeu) => `pixel-openspace:record-${jeu}`

/** Le meilleur score de ce jeu dans ce navigateur. */
export function lireRecord(jeu: Jeu): number {
  try {
    return Number(localStorage.getItem(cleRecord(jeu)) ?? 0)
  } catch {
    return 0
  }
}

/** L'écran d'une borne au repos, ou après une partie perdue. */
function ecranTitre(ctx: CanvasRenderingContext2D, jeu: Jeu, perdu: boolean, textes: Texts) {
  ctx.fillStyle = '#0b0d10'
  ctx.fillRect(0, 0, COTE, COTE)
  ctx.textAlign = 'center'
  if (perdu) {
    ctx.fillStyle = '#ef4444'
    ctx.font = '22px monospace'
    ctx.fillText(textes.arcade.gameOver, COTE / 2, COTE / 2 - 16)
  } else {
    ctx.fillStyle = jeu === 'snake' ? '#f472b6' : '#67e8f9'
    ctx.font = '18px monospace'
    ctx.fillText(textes.arcade.title[jeu === 'snake' ? 'snake' : 'breakout'], COTE / 2, COTE / 2 - 16)
  }
  ctx.fillStyle = '#e5e7eb'
  ctx.font = '12px monospace'
  ctx.fillText(perdu ? textes.arcade.replay : textes.arcade.pressPlay, COTE / 2, COTE / 2 + 14)
}

/**
 * Une borne d'arcade du coin gaming. Elle s'allume sur son écran titre et
 * attend qu'on appuie sur JOUER (ou Entrée, ou Espace) ; Échap la ferme. Le
 * record de chaque jeu reste dans ce navigateur.
 */
export function JeuArcade({ jeu, textes, fermer }: { jeu: Jeu; textes: Texts; fermer: () => void }) {
  const titre = textes.arcade.title[jeu === 'snake' ? 'snake' : 'breakout']
  const aide = textes.arcade.help[jeu === 'snake' ? 'snake' : 'breakout']
  const borne = BORNES[jeu]
  const [toile, setToile] = useState<HTMLCanvasElement | null>(null)
  const [score, setScore] = useState(0)
  const [record, setRecord] = useState(0)
  const [phase, setPhase] = useState<'titre' | 'jeu' | 'perdu'>('titre')
  const [partie, setPartie] = useState(0)

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- le record vit dans le navigateur, lu après l'ouverture
    setRecord(lireRecord(jeu))
  }, [jeu])

  /* Hors partie, l'écran titre ; en partie, le jeu tourne jusqu'à la défaite. */
  useEffect(() => {
    const ctx = toile?.getContext('2d')
    if (!ctx) return
    if (phase !== 'jeu') {
      ecranTitre(ctx, jeu, phase === 'perdu', textes)
      return
    }
    let total = 0
    return borne.lancer(ctx, {
      marquer: (points) => {
        total = points
        setScore(points)
      },
      perdre: () => {
        if (total > lireRecord(jeu)) {
          try {
            localStorage.setItem(cleRecord(jeu), String(total))
          } catch {
            /* Pas de stockage : le record ne survivra pas, tant pis. */
          }
          setRecord(total)
        }
        setPhase('perdu')
      },
    })
  }, [phase, partie, jeu, borne, textes, toile])

  const jouer = () => {
    setScore(0)
    setPartie((p) => p + 1)
    setPhase('jeu')
  }

  useEffect(() => {
    const touche = (e: KeyboardEvent) => {
      if ((e.key === 'Enter' || e.key === ' ') && phase !== 'jeu') {
        e.preventDefault()
        jouer()
      }
    }
    window.addEventListener('keydown', touche)
    return () => window.removeEventListener('keydown', touche)
  })

  return (
    <Dialog open onOpenChange={(ouverte) => !ouverte && fermer()}>
      <DialogContent className={`w-auto max-w-none border-4 sm:max-w-none ${borne.cadre} ${borne.fond}`}>
        <DialogHeader>
          <DialogTitle className={`font-mono tracking-widest ${borne.accent}`}>{titre}</DialogTitle>
        </DialogHeader>
        <canvas ref={setToile} width={COTE} height={COTE} className="block rounded border-2 border-black [image-rendering:pixelated]" />
        <DialogFooter className="flex-row items-center justify-between gap-4 sm:justify-between">
          <Badge variant="secondary" className="font-mono">
            {textes.arcade.score} {String(score).padStart(3, '0')}
          </Badge>
          <Button onClick={jouer} disabled={phase === 'jeu'} className="font-bold tracking-widest">
            {textes.arcade.play}
          </Button>
          <Badge variant="outline" className="font-mono">
            {textes.arcade.record} {String(record).padStart(3, '0')}
          </Badge>
        </DialogFooter>
        <p className="text-center text-xs text-muted-foreground">
          {aide} · <Kbd>Enter</Kbd> {textes.arcade.toPlay} · <Kbd>Esc</Kbd> {textes.arcade.toClose}
        </p>
      </DialogContent>
    </Dialog>
  )
}

/* ——— Le Snake des composants ——— */

const CASES = 20
const CASE = COTE / CASES

type Case = { x: number; y: number }

/* Ce que le serpent mange : des composants, chacun sa couleur. */
const COMPOSANTS = ['#22c55e', '#e3b95a', '#38bdf8', '#a855f7']

const DIRECTIONS: Record<string, Case> = {
  ArrowUp: { x: 0, y: -1 },
  ArrowDown: { x: 0, y: 1 },
  ArrowLeft: { x: -1, y: 0 },
  ArrowRight: { x: 1, y: 0 },
  z: { x: 0, y: -1 },
  s: { x: 0, y: 1 },
  q: { x: -1, y: 0 },
  d: { x: 1, y: 0 },
}

/** Un serpent en nappe de câbles RGB, qui avale des composants et grandit d'autant. */
function lancerSnake(ctx: CanvasRenderingContext2D, { marquer, perdre }: Partie) {
  let serpent: Array<Case> = [
    { x: 9, y: 10 },
    { x: 8, y: 10 },
    { x: 7, y: 10 },
  ]
  let direction: Case = { x: 1, y: 0 }
  let prochaine = direction
  let points = 0
  const poser = () => {
    let c: Case
    do c = { x: Math.floor(Math.random() * CASES), y: Math.floor(Math.random() * CASES) }
    while (serpent.some((s) => s.x === c.x && s.y === c.y))
    return { ...c, couleur: COMPOSANTS[Math.floor(Math.random() * COMPOSANTS.length)] }
  }
  let miam = poser()

  const dessiner = () => {
    ctx.fillStyle = '#0b0d10'
    ctx.fillRect(0, 0, COTE, COTE)
    ctx.fillStyle = '#111827'
    for (let i = 0; i < CASES; i++) for (let j = i % 2; j < CASES; j += 2) ctx.fillRect(i * CASE, j * CASE, CASE, CASE)
    // Le composant à avaler, avec ses pattes de puce.
    ctx.fillStyle = miam.couleur
    ctx.fillRect(miam.x * CASE + 3, miam.y * CASE + 3, CASE - 6, CASE - 6)
    ctx.fillStyle = '#9ca3af'
    for (let k = 0; k < 3; k++) {
      ctx.fillRect(miam.x * CASE + 4 + k * 3, miam.y * CASE + 1, 1, 2)
      ctx.fillRect(miam.x * CASE + 4 + k * 3, miam.y * CASE + CASE - 3, 1, 2)
    }
    serpent.forEach((s, i) => {
      ctx.fillStyle = i === 0 ? '#f8fafc' : `hsl(${(i * 24 + points * 10) % 360} 85% 60%)`
      ctx.fillRect(s.x * CASE + 1, s.y * CASE + 1, CASE - 2, CASE - 2)
    })
  }

  const avancer = () => {
    direction = prochaine
    const tete = { x: serpent[0].x + direction.x, y: serpent[0].y + direction.y }
    const mur = tete.x < 0 || tete.y < 0 || tete.x >= CASES || tete.y >= CASES
    if (mur || serpent.some((s) => s.x === tete.x && s.y === tete.y)) {
      clearInterval(t)
      perdre()
      return
    }
    serpent = [tete, ...serpent]
    if (tete.x === miam.x && tete.y === miam.y) {
      points += 1
      marquer(points)
      miam = poser()
    } else {
      serpent.pop()
    }
    dessiner()
  }

  const touche = (e: KeyboardEvent) => {
    const d = DIRECTIONS[e.key]
    if (!d) return
    e.preventDefault()
    // Pas de demi-tour sur soi-même.
    if (d.x !== -direction.x || d.y !== -direction.y) prochaine = d
  }
  window.addEventListener('keydown', touche)
  dessiner()
  const t = setInterval(avancer, 120)
  return () => {
    clearInterval(t)
    window.removeEventListener('keydown', touche)
  }
}

/* ——— Le Casse-puces ——— */

const COLONNES = 8
const RANGEES = 5
const BRIQUE = { largeur: 36, hauteur: 12, marge: 3, haut: 36 }
const RAQUETTE = { largeur: 56, hauteur: 6, y: COTE - 22 }
/* Une rangée par famille de puces : GPU, CPU, RAM, SSD, carte mère. */
const RANGS = ['#e3b95a', '#22c55e', '#38bdf8', '#a855f7', '#ef4444']

/**
 * Un casse-briques où les briques sont des puces : la raquette renvoie la
 * bille, chaque puce cassée rapporte dix points, et un tableau vidé en remet
 * un, plus rapide. Trois billes par partie.
 */
function lancerCasseBriques(ctx: CanvasRenderingContext2D, { marquer, perdre }: Partie) {
  const gauche = (COTE - COLONNES * (BRIQUE.largeur + BRIQUE.marge) + BRIQUE.marge) / 2
  const nouveauTableau = () =>
    Array.from({ length: RANGEES * COLONNES }, (_, i) => ({
      x: gauche + (i % COLONNES) * (BRIQUE.largeur + BRIQUE.marge),
      y: BRIQUE.haut + Math.floor(i / COLONNES) * (BRIQUE.hauteur + BRIQUE.marge),
      couleur: RANGS[Math.floor(i / COLONNES)],
      vivante: true,
    }))
  let briques = nouveauTableau()
  let raquette = (COTE - RAQUETTE.largeur) / 2
  let vitesse = 3.2
  let bille = { x: COTE / 2, y: RAQUETTE.y - 10, vx: 2, vy: -vitesse }
  let billes = 3
  let points = 0
  const appuyees = new Set<string>()

  const relancer = () => {
    bille = { x: raquette + RAQUETTE.largeur / 2, y: RAQUETTE.y - 10, vx: (Math.random() < 0.5 ? -1 : 1) * 2, vy: -vitesse }
  }

  const dessiner = () => {
    ctx.fillStyle = '#020617'
    ctx.fillRect(0, 0, COTE, COTE)
    for (const b of briques) {
      if (!b.vivante) continue
      ctx.fillStyle = b.couleur
      ctx.fillRect(b.x, b.y, BRIQUE.largeur, BRIQUE.hauteur)
      // Les pattes dorées de la puce.
      ctx.fillStyle = 'rgb(0 0 0 / 0.35)'
      ctx.fillRect(b.x + 4, b.y + 3, BRIQUE.largeur - 8, BRIQUE.hauteur - 6)
    }
    ctx.fillStyle = '#e5e7eb'
    ctx.fillRect(raquette, RAQUETTE.y, RAQUETTE.largeur, RAQUETTE.hauteur)
    ctx.fillStyle = '#22d3ee'
    ctx.fillRect(raquette, RAQUETTE.y + RAQUETTE.hauteur - 2, RAQUETTE.largeur, 2)
    ctx.fillStyle = '#f8fafc'
    ctx.fillRect(bille.x - 3, bille.y - 3, 6, 6)
    for (let i = 0; i < billes; i++) {
      ctx.fillStyle = '#f472b6'
      ctx.fillRect(8 + i * 10, 10, 6, 6)
    }
  }

  let image = 0
  const tour = () => {
    if (appuyees.has('ArrowLeft') || appuyees.has('q')) raquette -= 6
    if (appuyees.has('ArrowRight') || appuyees.has('d')) raquette += 6
    raquette = Math.max(0, Math.min(COTE - RAQUETTE.largeur, raquette))

    bille.x += bille.vx
    bille.y += bille.vy
    if (bille.x < 3 || bille.x > COTE - 3) bille.vx *= -1
    if (bille.y < 3) bille.vy = Math.abs(bille.vy)

    // La raquette renvoie la bille, d'autant plus en biais qu'elle frappe au bord.
    if (
      bille.vy > 0 &&
      bille.y >= RAQUETTE.y - 3 &&
      bille.y <= RAQUETTE.y + 4 &&
      bille.x >= raquette &&
      bille.x <= raquette + RAQUETTE.largeur
    ) {
      const decalage = (bille.x - (raquette + RAQUETTE.largeur / 2)) / (RAQUETTE.largeur / 2)
      bille.vx = decalage * 4
      bille.vy = -vitesse
    }

    for (const b of briques) {
      if (!b.vivante) continue
      if (bille.x > b.x && bille.x < b.x + BRIQUE.largeur && bille.y > b.y && bille.y < b.y + BRIQUE.hauteur) {
        b.vivante = false
        bille.vy *= -1
        points += 10
        marquer(points)
        break
      }
    }

    if (briques.every((b) => !b.vivante)) {
      vitesse += 0.6
      briques = nouveauTableau()
      relancer()
    }

    if (bille.y > COTE) {
      billes -= 1
      if (billes === 0) {
        dessiner()
        perdre()
        return
      }
      relancer()
    }

    dessiner()
    image = requestAnimationFrame(tour)
  }

  const bas = (e: KeyboardEvent) => {
    if (['ArrowLeft', 'ArrowRight', 'q', 'd'].includes(e.key)) {
      e.preventDefault()
      appuyees.add(e.key)
    }
  }
  const haut = (e: KeyboardEvent) => appuyees.delete(e.key)
  const souris = (e: MouseEvent) => {
    const r = ctx.canvas.getBoundingClientRect()
    raquette = ((e.clientX - r.left) / r.width) * COTE - RAQUETTE.largeur / 2
  }
  window.addEventListener('keydown', bas)
  window.addEventListener('keyup', haut)
  ctx.canvas.addEventListener('mousemove', souris)
  image = requestAnimationFrame(tour)
  return () => {
    cancelAnimationFrame(image)
    window.removeEventListener('keydown', bas)
    window.removeEventListener('keyup', haut)
    ctx.canvas.removeEventListener('mousemove', souris)
  }
}

/*
 * Ce que le visiteur a réglé derrière la roue dentée, tel qu'il est gardé dans
 * son navigateur. Relu champ par champ : une valeur abîmée ou d'une ancienne
 * version est ignorée plutôt que de faire planter la salle.
 */

import type { Language, ThemeName } from './types'

/** Ce que le visiteur a changé ; ce qu'il n'a pas touché suit les props. */
export type Preferences = {
  title?: string
  /** Le lieu de la météo à la fenêtre, à la place de celle des props. */
  weatherPlace?: string
  theme?: ThemeName
  language?: Language
  seasonal?: boolean
  night?: boolean
  motion?: boolean
  timeline?: boolean
}

export const THEMES: Array<ThemeName> = ['geek', 'eighties', 'gym', 'modern']
export const LANGUES: Array<Language> = ['en', 'fr']
export const LONGUEUR_ENSEIGNE = 24

const INTERRUPTEURS = ['seasonal', 'night', 'motion', 'timeline'] as const

/** Ne garde que les réglages valides d'un objet venu du stockage. */
export function nettoyerPreferences(brut: unknown): Preferences {
  if (!brut || typeof brut !== 'object' || Array.isArray(brut)) return {}
  const b = brut as Record<string, unknown>
  const p: Preferences = {}
  if (typeof b.title === 'string' && b.title.trim()) p.title = b.title.slice(0, LONGUEUR_ENSEIGNE)
  if (typeof b.weatherPlace === 'string' && b.weatherPlace.trim()) p.weatherPlace = b.weatherPlace
  if (THEMES.includes(b.theme as ThemeName)) p.theme = b.theme as ThemeName
  if (LANGUES.includes(b.language as Language)) p.language = b.language as Language
  for (const cle of INTERRUPTEURS) if (typeof b[cle] === 'boolean') p[cle] = b[cle]
  return p
}

const CLE = 'pixel-openspace:settings'

export function lirePreferences(): Preferences {
  try {
    return nettoyerPreferences(JSON.parse(localStorage.getItem(CLE) ?? '{}'))
  } catch {
    return {}
  }
}

export function ecrirePreferences(preferences: Preferences) {
  try {
    if (Object.keys(preferences).length) localStorage.setItem(CLE, JSON.stringify(preferences))
    else localStorage.removeItem(CLE)
  } catch {
    /* Navigation privée ou stockage bloqué : le réglage vaut pour cette visite. */
  }
}

