/** Où en est la recherche du lieu choisi dans les réglages. */
export type EtatMeteo = { etat: 'aucun' } | { etat: 'recherche' } | { etat: 'introuvable' } | { etat: 'trouve'; meteo: Weather }

/**
 * La météo du lieu tapé dans les réglages : cherchée une fois la frappe
 * finie, puis relue toutes les quinze minutes.
 */
export function useMeteoDuLieu(lieu: string | undefined, langue: Language): EtatMeteo {
  const [etat, setEtat] = useState<EtatMeteo>({ etat: 'aucun' })
  useEffect(() => {
    const cherche = lieu?.trim()
    if (!cherche) {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- plus de lieu choisi : la météo des props reprend
      setEtat({ etat: 'aucun' })
      return
    }
    let fini = false
    let endroit: Endroit | null = null
    const lire = async () => {
      try {
        endroit ??= await localiser(cherche, langue)
        const meteo = { ...(await lireMeteo(endroit)), place: endroit.nom ?? cherche }
        if (!fini) setEtat({ etat: 'trouve', meteo })
      } catch {
        if (!fini && !endroit) setEtat({ etat: 'introuvable' })
      }
    }
    setEtat({ etat: 'recherche' })
    // Une recherche par lieu, pas une par lettre tapée.
    const attente = setTimeout(lire, 700)
    const minuterie = setInterval(lire, 15 * 60_000)
    return () => {
      fini = true
      clearTimeout(attente)
      clearInterval(minuterie)
    }
  }, [lieu, langue])
  return etat
}

const NOMS_LANGUES: Array<[Language, string]> = [
  ['en', 'English'],
  ['fr', 'Français'],
]

/** Un réglage à interrupteur : son nom, une ligne d'explication, et l'interrupteur à droite. */
function Interrupteur({
  nom,
  aide,
  actif,
  changer,
  desactive,
}: {
  nom: string
  aide: ReactNode
  actif: boolean
  changer: (actif: boolean) => void
  desactive?: boolean
}) {
  const id = useId()
  return (
    <div className="flex items-start justify-between gap-4">
      <div className="flex flex-col gap-1">
        <Label htmlFor={id}>{nom}</Label>
        <p className="text-sm text-muted-foreground">{aide}</p>
      </div>
      <Switch id={id} checked={actif} onCheckedChange={changer} disabled={desactive} className="mt-0.5" />
    </div>
  )
}

/** Un choix parmi quelques boutons, celui retenu en avant. */
function Choix<T extends string>({
  nom,
  options,
  valeur,
  changer,
}: {
  nom: string
  options: Array<[T, string]>
  valeur: T
  changer: (v: T) => void
}) {
  return (
    <div className="flex flex-col gap-2">
      <Label>{nom}</Label>
      <ButtonGroup aria-label={nom} className="flex-wrap">
        {options.map(([v, libelle]) => (
          <Button key={v} size="sm" variant={valeur === v ? 'default' : 'outline'} aria-pressed={valeur === v} onClick={() => changer(v)}>
            {libelle}
          </Button>
        ))}
      </ButtonGroup>
    </div>
  )
}

export function Reglages({
  titre,
  titreOrigine,
  lieu,
  lieuOrigine,
  etatMeteo,
  theme,
  langue,
  saisons,
  nuit,
  mouvement,
  frise,
  son,
  alertes,
  alertesBloquees,
  changer,
  basculerSon,
  basculerAlertes,
  reinitialiser,
}: {
  /** L'enseigne choisie par le visiteur, vide s'il garde celle des props. */
  titre: string
  titreOrigine: string
  /** Le lieu tapé par le visiteur, vide s'il garde la météo des props. */
  lieu: string
  lieuOrigine?: string
  etatMeteo: EtatMeteo
  theme: ThemeName
  langue: Language
  saisons: boolean
  nuit: boolean
  mouvement: boolean
  frise: boolean
  son: boolean
  alertes: boolean
  alertesBloquees: boolean
  changer: (preferences: Preferences) => void
  basculerSon: () => void
  basculerAlertes: () => void
  reinitialiser: () => void
}) {
  const t = useTextes().settings
  // Ouverte et fermée à la main, sans `asChild` ni `render` : la même fenêtre marche avec les styles shadcn Radix et Base UI.
  const [ouverte, setOuverte] = useState(false)
  const idTitre = useId()
  const idLieu = useId()
  const aideMeteo =
    etatMeteo.etat === 'recherche'
      ? t.weatherSearching
      : etatMeteo.etat === 'introuvable'
        ? t.weatherNotFound
        : etatMeteo.etat === 'trouve'
          ? t.weatherFound(etatMeteo.meteo.place ?? lieu, etatMeteo.meteo.temperature)
          : null
  return (
    <Dialog open={ouverte} onOpenChange={setOuverte}>
      <Button variant="outline" size="icon-sm" aria-label={t.open} title={t.open} onClick={() => setOuverte(true)}>
        <SettingsIcon />
      </Button>
      <DialogContent className="max-h-[90svh] overflow-y-auto sm:max-w-md">
        <DialogHeader>
          <DialogTitle>{t.title}</DialogTitle>
          <DialogDescription>{t.description}</DialogDescription>
        </DialogHeader>
        <div className="flex flex-col gap-5">
          <div className="flex flex-col gap-2">
            <Label htmlFor={idTitre}>{t.sign}</Label>
            <Input
              id={idTitre}
              value={titre}
              placeholder={titreOrigine}
              maxLength={LONGUEUR_ENSEIGNE}
              onChange={(e) => changer({ title: e.target.value || undefined })}
            />
          </div>
          <div className="flex flex-col gap-2">
            <Label htmlFor={idLieu}>{t.weather}</Label>
            <Input
              id={idLieu}
              value={lieu}
              placeholder={lieuOrigine ?? t.weatherPlaceholder}
              onChange={(e) => changer({ weatherPlace: e.target.value || undefined })}
            />
            {aideMeteo ? (
              <p className={`text-sm ${etatMeteo.etat === 'introuvable' ? 'text-destructive' : 'text-muted-foreground'}`}>{aideMeteo}</p>
            ) : null}
          </div>
          <Choix nom={t.theme} options={THEMES.map((n) => [n, t.themes[n]])} valeur={theme} changer={(v) => changer({ theme: v })} />
          <Choix nom={t.language} options={NOMS_LANGUES} valeur={langue} changer={(v) => changer({ language: v })} />
          <Separator />
          <Interrupteur nom={t.sound} aide={t.soundHint} actif={son} changer={basculerSon} />
          <Interrupteur
            nom={t.alerts}
            aide={alertesBloquees ? t.alertsBlocked : t.alertsHint}
            actif={alertes}
            changer={basculerAlertes}
            desactive={alertesBloquees}
          />
          <Separator />
          <Interrupteur nom={t.seasonal} aide={t.seasonalHint} actif={saisons} changer={(v) => changer({ seasonal: v })} />
          <Interrupteur nom={t.night} aide={t.nightHint} actif={nuit} changer={(v) => changer({ night: v })} />
          <Interrupteur nom={t.motion} aide={t.motionHint} actif={mouvement} changer={(v) => changer({ motion: v })} />
          <Interrupteur nom={t.timeline} aide={t.timelineHint} actif={frise} changer={(v) => changer({ timeline: v })} />
        </div>
        <DialogFooter>
          <Button variant="ghost" onClick={reinitialiser}>
            {t.reset}
          </Button>
          <Button onClick={() => setOuverte(false)}>{t.done}</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

/*
 * La journée en frise, sous la salle : une ligne par agent, de minuit à
 * minuit, un point par passage (vert s'il s'est bien passé, rouge sinon), et
 * le trait de l'heure qu'il est. De quoi voir d'un coup d'œil qui a sauté un
 * passage cette nuit.
 */

import { Card, CardAction, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { useTextes } from './primitives'
import type { Agent } from './types'

const JOUR_MS = 86_400_000
const HEURES = [0, 3, 6, 9, 12, 15, 18, 21, 24]

export function Frise({ agents, maintenant, choisir }: { agents: Array<Agent>; maintenant: number; choisir: (id: string) => void }) {
  const t = useTextes()
  const minuit = new Date(maintenant)
  minuit.setHours(0, 0, 0, 0)
  const debut = minuit.getTime()
  const position = (ms: number) => `${Math.min(100, Math.max(0, ((ms - debut) / JOUR_MS) * 100))}%`
  // Seuls les passages d'aujourd'hui entrent dans la frise.
  const lignes = agents.map((a) => ({ agent: a, passages: (a.runs ?? []).filter((r) => Date.parse(r.at) >= debut) }))
  const total = lignes.reduce((n, l) => n + l.passages.length, 0)
  const rates = lignes.reduce((n, l) => n + l.passages.filter((r) => r.ok === false).length, 0)
  const heure = (iso: string) => new Date(iso).toLocaleTimeString(t.locale, { hour: '2-digit', minute: '2-digit' })

  return (
    <Card>
      <CardHeader>
        <CardTitle>{t.timeline.title}</CardTitle>
        <CardAction className="text-xs text-muted-foreground">
          {t.timeline.runs(total)}
          {rates ? <span className="text-destructive"> · {t.timeline.failed(rates)}</span> : null}
        </CardAction>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-[minmax(6rem,9rem)_1fr] gap-x-3 gap-y-1.5 text-xs">
          {/* Les heures. */}
          <span />
          <div className="relative h-4 text-[0.65rem] text-muted-foreground">
            {HEURES.map((h) => (
              <span
                key={h}
                className={`absolute whitespace-nowrap ${h === 0 ? '' : h === 24 ? '-translate-x-full' : '-translate-x-1/2'}`}
                style={{ left: `${(h / 24) * 100}%` }}
              >
                {t.timeline.hour(h)}
              </span>
            ))}
          </div>

          {lignes.map(({ agent, passages }) => (
            <div key={agent.id} className="contents">
              <button type="button" onClick={() => choisir(agent.id)} className="truncate text-left hover:text-primary">
                {agent.emoji ? <span aria-hidden>{agent.emoji} </span> : null}
                {agent.name}
              </button>
              <div className="relative h-5 rounded bg-muted/50">
                {[6, 12, 18].map((h) => (
                  <span key={h} className="absolute inset-y-0 w-px bg-border" style={{ left: `${(h / 24) * 100}%` }} />
                ))}
                {passages.map((r, i) => (
                  <span
                    key={`${r.at}-${i}`}
                    title={`${heure(r.at)} · ${r.message || t.timeline.run}`}
                    className={`absolute top-1/2 size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full ring-2 ring-background ${
                      r.ok === false ? 'bg-red-500' : 'bg-emerald-500'
                    }`}
                    style={{ left: position(Date.parse(r.at)) }}
                  />
                ))}
                <span className="absolute inset-y-[-2px] w-0.5 bg-primary" style={{ left: position(maintenant) }} />
              </div>
            </div>
          ))}
        </div>
      </CardContent>
    </Card>
  )
}

/*
 * La vraie météo d'un lieu, par Open-Meteo : gratuit, sans clé, et ouvert aux
 * navigateurs (CORS). Le lieu est une ville (« Lanton », « Lyon, France ») ou
 * des coordonnées (« 44.70,-1.04 »). Sans React : le serveur local s'en sert aussi.
 */

import type { Language, Sky, Weather } from './types'

/** Les codes météo de l'OMS, ramenés à ce qu'une fenêtre en pixels sait dessiner. */
export function cielDe(code: number): Sky {
  if (code === 0 || code === 1) return 'clear'
  if (code === 2 || code === 3) return 'clouds'
  if (code === 45 || code === 48) return 'fog'
  if ((code >= 71 && code <= 77) || code === 85 || code === 86) return 'snow'
  if (code >= 95) return 'storm'
  return 'rain'
}

/** « 44.70,-1.04 » : des coordonnées toutes prêtes, sans passer par la recherche de ville. */
export function coordonnees(lieu: string): { latitude: number; longitude: number } | null {
  const m = lieu.trim().match(/^(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)$/)
  if (!m) return null
  const [latitude, longitude] = [Number(m[1]), Number(m[2])]
  return Math.abs(latitude) <= 90 && Math.abs(longitude) <= 180 ? { latitude, longitude } : null
}

export type Endroit = { latitude: number; longitude: number; nom?: string }

/** Trouve une ville ; « Lyon, France » garde le premier mot pour la recherche. */
export async function localiser(lieu: string, langue: Language): Promise<Endroit> {
  const direct = coordonnees(lieu)
  if (direct) return direct
  const nom = lieu.split(',')[0].trim()
  const url = `https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(nom)}&count=1&language=${langue}&format=json`
  const reponse = await fetch(url, { signal: AbortSignal.timeout(5000) })
  const { results } = (await reponse.json()) as { results?: Array<{ latitude: number; longitude: number; name: string }> }
  if (!results?.length) throw new Error(`place not found: ${lieu}`)
  return { latitude: results[0].latitude, longitude: results[0].longitude, nom: results[0].name }
}

export async function lireMeteo(endroit: Endroit): Promise<Omit<Weather, 'place'>> {
  const url =
    `https://api.open-meteo.com/v1/forecast?latitude=${endroit.latitude}&longitude=${endroit.longitude}` +
    '&current=temperature_2m,weather_code,is_day&timezone=auto'
  const reponse = await fetch(url, { signal: AbortSignal.timeout(5000) })
  if (!reponse.ok) throw new Error(`weather: HTTP ${reponse.status}`)
  const { current } = (await reponse.json()) as { current: { temperature_2m: number; weather_code: number; is_day: number } }
  return { temperature: Math.round(current.temperature_2m), sky: cielDe(current.weather_code), day: current.is_day === 1 }
}

import type { CSSProperties } from 'react'

/** Where an agent stands right now. */
export type AgentStatus =
  /** Running at this very moment: it sits at its desk, screen on, typing. */
  | 'working'
  /** Up to date: it wanders off to the coffee machine between runs. */
  | 'ok'
  /** Missed its last run: it dozes at its desk. */
  | 'late'
  /** Its last run failed: its PC smokes and the lead comes to see it. */
  | 'failed'
  /** Not loaded at all: empty chair, a post-it on a dark screen. */
  | 'off'
  /** Never ran yet. */
  | 'never'
  /** Runs only when asked. */
  | 'on-demand'

/** One of your scheduled jobs, workers or AI agents, as the open space shows it. */
export type Agent = {
  /** Stable identifier: it also picks the agent's hair and hoodie colours. */
  id: string
  name: string
  emoji?: string
  /** One line about what it does; it says it when clicked. */
  role?: string
  status: AgentStatus
  /** What it said last time, shown on its card and in its speech bubble when it finishes. */
  lastMessage?: string | null
  /** ISO date of its last run. */
  lastRun?: string | null
  /** ISO date of its next run: its screen counts down the last ten minutes. */
  nextRun?: string | null
  /** Its rhythm, in words: "every 30 min", "daily at 7:30". */
  schedule?: string
  /** Hours without a run after which its plant wilts and dust covers its screen. Default 72. */
  staleAfterHours?: number
  /** Today's runs, oldest first: one dot each on the day timeline under the room. */
  runs?: Array<AgentRun>
}

/** One run of an agent, for the day timeline. */
export type AgentRun = {
  /** ISO date of the run. */
  at: string
  /** False for a failed run: a red dot. Default true. */
  ok?: boolean
  /** Shown when hovering the dot. */
  message?: string
}

/** A tile of the big wall screen. */
export type WallTile = {
  label: string
  value: string | number
  tone?: 'neutral' | 'ok' | 'info' | 'warn' | 'alert'
  /** A gauge under the value, from 0 to 1. */
  progress?: number
}

export type Sky = 'clear' | 'clouds' | 'fog' | 'rain' | 'snow' | 'storm'

/** The weather behind the lead's window. */
export type Weather = {
  temperature: number
  sky: Sky
  /** False at night: moon and stars instead of the sun. */
  day: boolean
  /** Written under the window. */
  place?: string
}

/** The props in the room that can be clicked. */
export type SceneObject = 'workbench' | 'tv' | 'server-rack' | 'vending-machine' | 'fridge' | 'cpu-box' | 'gpu-box' | 'ram-box'

export type Language = 'en' | 'fr'

/** The look of the room: a geek open space today, a corporate office around 1986, or a gym where every job rides an exercise bike. */
export type ThemeName = 'geek' | 'eighties' | 'gym' | 'modern'

export type OpenSpaceProps = {
  /** Up to five per row; rows are added as needed. */
  agents: Array<Agent>
  /**
   * The lead, in the glass office: it does its rounds while working, sits
   * with a failed agent until it recovers, and reports in front of the wall
   * screen. A decorative lead sits there when none is given.
   */
  lead?: Agent
  /** The neon sign on the main room wall. */
  title?: string
  /** Up to four tiles on the big wall screen. */
  wall?: Array<WallTile>
  /** What the lead announces in front of the wall screen after its rounds. */
  announcements?: Array<string>
  weather?: Weather | null
  /** A counter: each time it goes up, a visitor walks in to greet the lead. */
  visitors?: number
  /** A counter: each time it goes up, a courier drops a parcel by the boxes. */
  deliveries?: number
  /** Confetti over the whole room: a birthday, a launch, a record month. */
  celebrate?: boolean
  /** The day timeline under the room, when agents have `runs`. Default true. */
  timeline?: boolean
  language?: Language
  /** The look of the room: furniture, outfits, break corners. Default 'geek'. */
  theme?: ThemeName
  /** Halloween all October, Christmas all December, Easter for the two weeks before Easter Monday. Default true. */
  seasonal?: boolean
  /** From what hour to what hour everybody stays at their desk. Default [22, 6]. */
  nightHours?: [number, number]
  /** The fullscreen button and the settings gear above the scene. Default true. */
  toolbar?: boolean
  /** Where each prop leads when clicked; a prop without a link is not clickable. */
  objectLinks?: Partial<Record<SceneObject, string>>
  /** Called instead of following the link, for client-side routers. */
  onObjectClick?: (object: SceneObject, href: string) => void
  /** Shows a "Run now" button on each agent's card. */
  onRun?: (agent: Agent) => void | Promise<void>
  /** The current time, for server rendering: avoids a hydration mismatch on clocks and countdowns. */
  now?: number
  className?: string
  style?: CSSProperties
}

/**
 * Les fêtes de la salle : Halloween tout octobre, Noël tout décembre, et
 * Pâques des deux semaines qui la précèdent jusqu'au lundi de Pâques.
 */
export type Fete = 'halloween' | 'noel' | 'paques' | null

/** Le dimanche de Pâques d'une année, par l'algorithme grégorien (Meeus, Jones, Butcher). */
export function dimancheDePaques(annee: number): Date {
  const a = annee % 19
  const b = Math.floor(annee / 100)
  const c = annee % 100
  const d = Math.floor(b / 4)
  const e = b % 4
  const f = Math.floor((b + 8) / 25)
  const g = Math.floor((b - f + 1) / 3)
  const h = (19 * a + b - d - g + 15) % 30
  const i = Math.floor(c / 4)
  const k = c % 4
  const l = (32 + 2 * e + 2 * i - h - k) % 7
  const m = Math.floor((a + 11 * h + 22 * l) / 451)
  const mois = Math.floor((h + l - 7 * m + 114) / 31)
  const jour = ((h + l - 7 * m + 114) % 31) + 1
  return new Date(annee, mois - 1, jour)
}

const JOUR_MS = 86_400_000

export function fete(maintenant: number): Fete {
  const d = new Date(maintenant)
  if (d.getMonth() === 9) return 'halloween'
  if (d.getMonth() === 11) return 'noel'
  const paques = dimancheDePaques(d.getFullYear()).getTime()
  const aujourdhui = new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime()
  // Deux semaines avant le dimanche de Pâques, jusqu'au lundi de Pâques inclus.
  if (aujourdhui >= paques - 14 * JOUR_MS && aujourdhui <= paques + JOUR_MS) return 'paques'
  return null
}

